<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility\TemplateVersionVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionReadGateway;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionFilter;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionCursor;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVersionListUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateVersionVisibilityService $visibility,
    private readonly TemplateVersionReadGateway $reader
  ) {
  }

  public function allowList(): Allow
  {
    $this->logDebug("Check allow of list usecase for Template version");
    $span = $this->startSpan("Check allow of list usecase for Template version");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVersionListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function count(TemplateVersionFilter $filter): int
  {
    $this->logDebug("Run list usecase for Template version");
    $span = $this->startSpan("Run list usecase for Template version");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Template version');
      }
      return $this->visibility->countVisibles($filter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function list(TemplateVersionFilter $filter, ?TemplateVersionCursor $cursor = null): TemplateVersionAttributesSlide
  {
    $this->logDebug("Run list usecase for Template version");
    $span = $this->startSpan("Run list usecase for Template version");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
      }
      $slide = $this->visibility->listVisibles($filter, $cursor);
      return new TemplateVersionAttributesSlide($slide->nextCursor(), array_map( fn($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values() ));
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
